/**
 * "Blocked by" links between issues. Every method takes `orgId` first and only reads or writes links inside that organization.
 *
 * Must call (do not reimplement): orgPredicate, toIssueDependency
 */
import { and, asc, eq, isNull, notInArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { CLOSED_ISSUE_STATUSES, type Issue, type IssueDependency } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toIssue, toIssueDependency } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type { IssueId, OrgId, ProjectId, UserId } from "@/types/common";

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

export async function insertDependency(input: {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
  createdBy: UserId;
}): Promise<IssueDependency> {
  const row = getDb()
    .insert(issueDependencies)
    .values({
      orgId: input.orgId,
      issueId: input.issueId,
      blockerId: input.blockerId,
      createdBy: input.createdBy,
      createdAt: toIsoTimestamp(new Date()),
    })
    .returning()
    .get();
  return toIssueDependency(row);
}

/** Resolves `true` only when a link existed and was removed. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const result = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .run();
  return result.changes > 0;
}

/** Ids of the issues `issueId` is directly blocked by, archived or not. */
export async function listBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ blockerId: issueDependencies.blockerId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
      ),
    )
    .all();
  return rows.map((row) => row.blockerId as IssueId);
}

/** Ids of the issues that `blockerId` directly blocks, archived or not. */
export async function listBlockedIssueIds(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ issueId: issueDependencies.issueId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all();
  return rows.map((row) => row.issueId as IssueId);
}

/** Live blockers of `issueId` (open or closed), ordered by issue number. */
export async function listLiveBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ blocker: issues })
    .from(issueDependencies)
    .innerJoin(issues, eq(issues.id, issueDependencies.blockerId))
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        orgPredicate(issues.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        isNull(issues.archivedAt),
      ),
    )
    .orderBy(asc(issues.number))
    .all();

  const blockers = rows.map((row) => row.blocker);
  const labels = await listLabelsForIssues(
    orgId,
    blockers.map((row) => row.id as IssueId),
  );
  return blockers.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

/**
 * Blocker ids inside `projectId` that are still open (live and not done or
 * canceled) and block at least one issue. Read before a project cascade so
 * the caller knows which blockers the cascade is about to close.
 */
export async function listOpenBlockerIdsInProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .selectDistinct({ blockerId: issueDependencies.blockerId })
    .from(issueDependencies)
    .innerJoin(issues, eq(issues.id, issueDependencies.blockerId))
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        isNull(issues.archivedAt),
        notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
      ),
    )
    .all();
  return rows.map((row) => row.blockerId as IssueId);
}

