/**
 * "Blocked by" links between issues: recording and removing them, the completion gate on `done`, and the `issue_unblocked` notification once a blocker closes.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Unsubscribe } from "@/types/event";

/** Raised when `done` is requested while the issue still has open blockers. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly blockerIds: readonly IssueId[]) {
    super(`Issue is blocked by ${blockerIds.length} open issue(s)`);
    this.name = "IssueBlockedError";
  }
}

/** Raised when a link would make an issue (transitively) block itself. */
class IssueDependencyCycleError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: IssueId,
    readonly blockerId: IssueId,
  ) {
    super(`Issue ${issueId} cannot be blocked by ${blockerId}: it would form a cycle`);
    this.name = "IssueDependencyCycleError";
  }
}

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/** Open means live and not done or canceled. */
function isOpen(issue: Issue): boolean {
  return issue.archivedAt === null && !isClosedStatus(issue.status);
}

async function loadIssue(orgId: OrgId, issueId: IssueId): Promise<Issue> {
  return requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
}

/**
 * Records "`issueId` is blocked by `blockerId`". Editing the blocked issue is
 * the required permission. Re-adding an existing link returns it unchanged.
 */
export async function addBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = await loadIssue(input.orgId, input.issueId);
  const blocker = await loadIssue(input.orgId, input.blockerId);
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing !== null) return existing;

  if (await reachesBlocker(input.orgId, input.blockerId, input.issueId)) {
    throw new IssueDependencyCycleError(input.issueId, input.blockerId);
  }

  return dependencyRepo.insertDependency({
    orgId: input.orgId,
    issueId: input.issueId,
    blockerId: input.blockerId,
    createdBy: actor.userId,
  });
}

/** Resolves `true` when a link was removed, `false` when there was none. */
export async function removeBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = await loadIssue(input.orgId, input.issueId);
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

/** Live blockers of `issueId`, open or closed, ordered by issue number. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = await loadIssue(orgId, issueId);
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listLiveBlockers(orgId, issueId);
}

/**
 * The completion gate. Throws `IssueBlockedError` naming every open blocker of
 * `issueId`; passes silently when there are none.
 */
export async function assertNoOpenBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  const open = (await dependencyRepo.listLiveBlockers(orgId, issueId)).filter(
    isOpen,
  );
  if (open.length > 0) {
    throw new IssueBlockedError(open.map((blocker) => blocker.id));
  }
}

/**
 * Called once the given blockers have closed. Each issue they block that is
 * still open, has an assignee and has no open blocker left gets exactly one
 * `issue_unblocked` notification, even when several of its blockers closed
 * together.
 */
export async function releaseBlockedIssues(
  orgId: OrgId,
  blockerIds: readonly IssueId[],
  actorId: UserId | null,
): Promise<void> {
  const candidates = new Set<IssueId>();
  for (const blockerId of blockerIds) {
    for (const blockedId of await dependencyRepo.listBlockedIssueIds(
      orgId,
      blockerId,
    )) {
      candidates.add(blockedId);
    }
  }

  for (const blockedId of candidates) {
    const blocked = await issueRepo.findIssueById(orgId, blockedId);
    if (!blocked || !isOpen(blocked) || blocked.assigneeId === null) continue;

    const blockers = await dependencyRepo.listLiveBlockers(orgId, blockedId);
    if (blockers.some(isOpen)) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "An issue is unblocked",
      body: `Issue ${blocked.id} is no longer blocked`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

