    await releaseBlockedIssues(payload.orgId, [payload.issueId], payload.actorId);
  });

  const offArchived = subscribe("issue.archived", async (payload) => {
    // Archiving does not touch `status`, so the stored status is the one the
    // blocker had just before it was archived.
    const archived = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!archived || isClosedStatus(archived.status)) return;
    await releaseBlockedIssues(payload.orgId, [payload.issueId], payload.actorId);
  });

  return () => {
    offStatus();
    offArchived();
  };
}

/**
 * True when `target` is reachable from `start` by following "blocked by"
 * links, i.e. `start` is already (transitively) blocked by `target`.
