cat > tests/services/zz-scratch-dependency.test.ts <<'EOF'
import { beforeAll, afterAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import * as depService from "@/server/services/issue-dependency-service";
import * as notificationService from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("deps", "growth");
  registerEventHandlers();
});
afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

async function mk(title: string, assigneeId: any = null) {
  return issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title, assigneeId }));
}
async function notifsFor(userId: any) {
  const page = await notificationService.listNotifications(tenant.actors.owner, { orgId: tenant.org.id, recipientId: userId, unreadOnly: false, limit: 50, cursor: null } as any);
  return page.items.filter((n) => n.kind === "issue_unblocked");
}

describe("scratch issue dependencies", () => {
  it("links, gates, cycles, notifies", async () => {
    const a = await mk("Alpha blocked");
    const b = await mk("Beta blocker");
    const c = await mk("Gamma blocker");
    const orgId = tenant.org.id;
    const m = tenant.actors.member;

    const link = await depService.addBlocker(m, { orgId, issueId: a.id, blockerId: b.id });
    expect(link.createdBy).toBe(tenant.userIds.member);
    const again = await depService.addBlocker(m, { orgId, issueId: a.id, blockerId: b.id });
    expect(again.createdAt).toBe(link.createdAt);
    await depService.addBlocker(m, { orgId, issueId: a.id, blockerId: c.id });
    await expect(depService.addBlocker(m, { orgId, issueId: b.id, blockerId: a.id })).rejects.toThrow();
    await expect(depService.addBlocker(m, { orgId, issueId: a.id, blockerId: a.id })).rejects.toThrow();

    // gate
    const err = await issueService.changeIssueStatus(m, { orgId, issueId: a.id, status: "done" }).catch((e) => e);
    expect(err).toBeInstanceOf(depService.IssueBlockedError);
    expect([...err.blockerIds].sort()).toEqual([b.id, c.id].sort());

    const listed = await depService.listBlockers(m, orgId, a.id);
    expect(listed.map((i) => i.number)).toEqual([b.number, c.number]);

    // assignee for a: admin
    const assigned = await issueService.assignIssue(tenant.actors.owner, { orgId, issueId: a.id, assigneeId: tenant.userIds.admin } as any);
    expect(assigned.assigneeId).toBe(tenant.userIds.admin);

    // close b (member closes) -> still blocked by c, no notification
    await issueService.changeIssueStatus(m, { orgId, issueId: b.id, status: "done" });
    expect(await notifsFor(tenant.userIds.admin)).toHaveLength(0);

    // done -> canceled: closed->closed no notify. c: in_progress -> canceled unblocks
    await issueService.changeIssueStatus(m, { orgId, issueId: c.id, status: "canceled" });
    const after = await notifsFor(tenant.userIds.admin);
    expect(after).toHaveLength(1);
    expect(after[0]?.href).toBe(`/issues/${a.id}`);
    expect(after[0]?.actorId).toBe(tenant.userIds.member);

    // now done works
    const done = await issueService.changeIssueStatus(m, { orgId, issueId: a.id, status: "done" });
    expect(done.status).toBe("done");

    // remove returns boolean
    expect(await depService.removeBlocker(m, { orgId, issueId: a.id, blockerId: b.id })).toBe(true);
    expect(await depService.removeBlocker(m, { orgId, issueId: a.id, blockerId: b.id })).toBe(false);
  });

  it("archive unblocks, once; project cascade unblocks", async () => {
    const x = await mk("X blocked", tenant.userIds.admin);
    const y = await mk("Y blocker");
    const z = await mk("Z blocker");
    const orgId = tenant.org.id;
    await depService.addBlocker(tenant.actors.member, { orgId, issueId: x.id, blockerId: y.id });
    await depService.addBlocker(tenant.actors.member, { orgId, issueId: x.id, blockerId: z.id });
    const before = (await notifsFor(tenant.userIds.admin)).length;
    await issueService.archiveIssue(tenant.actors.member, orgId, y.id);
    expect((await notifsFor(tenant.userIds.admin)).length).toBe(before);
    await issueService.archiveIssue(tenant.actors.member, orgId, z.id);
    expect((await notifsFor(tenant.userIds.admin)).length).toBe(before + 1);
  });

  it("rejects cross-org and unknown ids; viewer denied", async () => {
    const q = await mk("Q");
    await expect(depService.addBlocker(tenant.actors.member, { orgId: "other" as any, issueId: q.id, blockerId: q.id })).rejects.toThrow();
    await expect(depService.addBlocker(tenant.actors.member, { orgId: tenant.org.id, issueId: q.id, blockerId: "nope" as any })).rejects.toThrow(/not found/i);
    await expect(depService.addBlocker(tenant.actors.viewer, { orgId: tenant.org.id, issueId: q.id, blockerId: q.id })).rejects.toThrow();
  });
});
EOF
